```javascript
function isPrime(num) {
  if (num <= 1) return false; // Numbers less than or equal to 1 are not primes
  for (let i = 2; i < Math.sqrt(num) + 1; i++) {
    if (num % i === 0) return false; // If the number can be evenly divided by another number, it's not prime
  }
  return true;
}

function checkPrimesInArray(arr) {
  arr.forEach(number => {
    if (isPrime(number)) console.log(number);
  });
}

// Test the function with an array of 5 numbers
const numbers = [4, 6, 7, 13, 17];
checkPrimesInArray(numbers);
```
This example will check the array `[4, 6, 7, 13, 17]` for prime numbers and will output `7` and `13` when run.

