        return 1;
    }

    int count = 0;
    std::string line;

    while (std::getline(file, line)) {
        // Split each line into words using space as delimiter
        auto words = split(line);

        for (const auto &word : words) {
            if (word == target_word) {
                ++count;
            }
        }
